const t = $('When Called by Agent').item.json;
const token = $('Create Review Token').item.json.token;
const link = (d) => $env.WEBHOOK_URL + 'webhook/review-decision?id=' + $json.ticket_id + '&token=' + token + '&decision=' + d;
const esc = (s) => String(s ?? '-').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
return { json: {
  subject: 'Support-Anfrage / Support request #' + $json.ticket_id + ' (chat)',
  html: [
    '<h3>Support-Anfrage aus dem Chat / Support request from chat</h3>',
    '<table cellpadding="4">',
    '<tr><td><b>Ticket</b></td><td>#' + $json.ticket_id + '</td></tr>',
    '<tr><td><b>Customer email</b></td><td>' + esc(t.customer_email) + '</td></tr>',
    '<tr><td><b>Language</b></td><td>' + esc(t.language) + '</td></tr>',
    '<tr><td><b>Chat session</b></td><td>' + esc(t.session_id) + '</td></tr>',
    '</table>',
    '<p><b>Summary:</b><br>' + esc(t.summary).replace(/\n/g, '<br>') + '</p>',
    '<p><a href="' + link('approve') + '">✅ Erledigt / Mark resolved</a> &nbsp; <a href="' + link('reject') + '">✖ Verwerfen / Dismiss</a></p>',
  ].join('\n'),
} };

